def check_digests_present_and_used(self, manifest_files, digests_used):
    if not manifest_files:
        raise ValueError("Please provide at least one manifest file")
    if not digests_used:
        raise ValueError("Please provide at least one digest to check")

    # check if digests in manifest are present in digests_used
    digests_present = set()
    for manifest_file in manifest_files:
        with open(manifest_file, "r") as f:
            digests = f.read().splitlines()
        digests_present |= set(digests)

    if not digests_present:
        raise ValueError("No digests found in manifest files")

    # check if digests in manifest are used
    digests_used_set = set(digests_used)
    for manifest_file in manifest_files:
        with open(manifest_file, "r") as f:
            lines = f.readlines()

        for line in lines:
            if line[0].lower() == "using" and line[1:].split(":")[0] in digests_used_set:
                digests_used_set.remove(line[1:].split(":")[0])

    if digests_used_set:
        raise ValueError("The following digests are not used in the manifest: " + ", ".join(digests_used_set))

    return True

