def absorb(self, args):
    result = []
    for arg in args:
        if isinstance(arg, LogicalExpression):
            expr = arg
            neg = isinstance(expr, Negation)
            if neg:
                expr = expr.expr
            if isinstance(expr, Disjunction):
                left = isinstance(expr.left, LogicalExpression) and neg
                right = isinstance(expr.right, LogicalExpression) and neg
                if left and right:
                    result.append(expr.left)
                elif left:
                    result.append(expr.left)
                elif right:
                    result.append(expr.right)
            elif isinstance(expr, Conjunction):
                left = isinstance(expr.left, LogicalExpression) and neg
                right = isinstance(expr.right, LogicalExpression) and neg
                if left and right:
                    result.append(expr.right)
                elif left:
                    result.append(expr.right)
                elif right:
                    result.append(expr.left)
            else:
                result.append(arg)
        else:
            result.append(arg)
    return result

def absorb(self, args):
    if not args:
        return []
    else:
        head = args[0]
        tail = absorb(args[1:])
        if head == "~":
            return tail
        elif head == "&" or head == "|":
            a, b = tail
            if head == "&":
                return [a]
            else:
