  // Given a timezone-aware datetime in a given timezone, calculates a timezone-aware datetime in a new timezone.
  // Since this is the one time that we *know* we have an unambiguous datetime object, we take this opportunity to determine whether the datetime is ambiguous and in a "fold" state (e.g. if it's the first occurrence, chronologically, of the ambiguous datetime).
  // :param dt:
  //   A timezone-aware datetime.datetime object.

  // store the offset from UTC into a variable
  double offset = getOffset( dt );

  // if the datetime is ambiguous and in a "fold" state
  if ( isFold( dt ) ) {
    // return the utc offset of the previously selected datetime
    return getUTC() - offset;
  }
  else {
    // return the given utc offset
    return offset;
  }
}

def _fromutc(self, dt):
    if dt.tzinfo.utcoffset(dt) is not None:
        raise ValueError("Input parameter must be a UTC datetime")
    else:
        newdt = super().fromutc(dt)
        is_duplicate = (newdt.utcoffset().nanoseconds == 0) or (newdt.utcoffset().nanoseconds == 7200000000000)
        if is_duplicate:
            newdt = newdt.replace(fold=1)
        return newdt

def _fromutc(self, dt):
        # Determine whether the datetime is ambiguous and in a "fold" state
        if dt.dst() == 0:
            dt = dt.replace(fold=1)
        else:
            dt = dt.replace(fold=0)
        return dt

def _fromutc(self, dt):
    # Determine if the datetime is ambiguous and in a "fold" state
    if isinstance(dt, datetime.datetime) and dt.tzinfo is not None:
        fold = self.is_ambiguous(dt)
    else:
        fold = False

    # Convert the datetime to the new timezone
    dt = self.tzinfo.fromutc(dt.replace(tzinfo=None))

    # Determine if the datetime is in a "fold" state
    if fold:
        # Convert the datetime to a simple (unfolded) datetime
        dt = self.tzinfo._determine_offset(dt)

    return dt

def normalized(self):
    norm_rel = relativedelta()
    for name in relativedelta._fields:
        value = getattr(self, name)
        if name in ['years', 'months', 'days', 'hours', 'minutes', 'seconds', 'milliseconds']:
            norm_rel.set(name, int(value))
        else:
            norm_rel.set(name, value)
    return norm_rel

