def subprocess_run_helper(func, *args, timeout, extra_env=None):
    if not callable(func):
        raise TypeError(f"first argument must be a callable function, got {type(func).__name__}")

    command = [func.__module__, *args]
    env = os.environ.copy()
    if extra_env is not None:
        env.update(extra_env)

    subprocess_result = subprocess.run(command, timeout=timeout, env=env)
    output = subprocess_result.stdout.decode("utf-8")
    if subprocess_result.returncode != 0:
        raise subprocess.CalledProcessError(subprocess_result)

    return output

