    for node in graph.subject_nodes():
        for parent in graph.objects(subject=node, predicate=prop):
            if parent not in roots:
                roots.add(parent)
    return roots

def find_roots(graph: graph, prop: URIRef, roots: Optional[Set[Node]] = None) -> Set[Node]:
    if roots is None:
        roots = []
    for parent, child in dep_graph(graph, prop):
        if child not in roots:
            roots.append(child)
        for grandchild in dep_graph(graph, prop, parent):
            if grandchild not in roots:
                roots.append(grandchild)
    return roots

