inline std::map<std::vector<T>, ProtocolHandler> protocol_handlers(const std::tuple<T> &protocol_version = std::tuple<T>()) {
    std::map<std::vector<T>, ProtocolHandler> handlers;

    if (protocol_version.size() == 2) {
        std::vector<T> version = {protocol_version.first, protocol_version.second};
        handlers.insert(std::pair<std::vector<T>, ProtocolHandler>(version, ProtocolHandler()));
    } else {
        for (auto &handler : m_handlers) {
            handlers.insert(std::pair<std::vector<T>, ProtocolHandler>(std::vector<T>{handler->get_version()}, ProtocolHandler(handler->get_version())));
        }
    }

    return handlers;
