def list_of_file_names(settings_dirs, spec_option):
    """Create a list of file names based on the settings and spec options provided.

    Args:
        settings_dirs (list): A list of settings directories to search for files.
        spec_option (str): A string representing the spec option used to search for files.

    Returns:
        list: A list of file names matching the spec options.
    """
    file_names = []
    for settings_dir in settings_dirs:
        for root, _, files in os.walk(settings_dir):
            for file in files:
                if file.startswith(spec_option):
                    file_names.append(os.path.join(root, file))
    return file_names

