        raise ValueError("Invalid input, ir_workspace and ir_plugin are required")
    if not playbook_path:
        raise ValueError("Invalid input, playbook_path is required")
    if not os.path.isfile(playbook_path):
        raise ValueError(f"playbook_path: '{playbook_path}' does not exist or is not a file")
    if ansible_args:
        ansible_args = json.dumps(ansible_args)

    command = f"ansible-playbook {playbook_path} {ansible_args}"
    if verbose:
        command += f"--verbose={verbose}"
    if extra_vars:
        for k, v in extra_vars.items():
            command += f"--extra-vars {k}={v}"
    command += " "
    output = ir_plugin.exec_shell(command)
    return output

