def _convert_non_cli_args(parser_name: str, values_dict: Dict[str, str]) -> None:
    def is_digit(value: str):
        """Checks if a value is an integer."""
        try:
            int(value)
        except ValueError:
            return False
        return True

    def is_float(value: str):
        """Checks if a value is a float."""
        try:
            float(value)
        except ValueError:
            return False
        return True

    def cast_to_type(arg_type: str, value: str) -> Any:
        """Casts a value to the specified type."""
        if arg_type in ('int', 'integer'):
            return int(value)
        if arg_type in ('float', 'decimal'):
            return float(value)
        if arg_type in ('bool', 'boolean'):
            return value.lower() == 'true'
        return value

    for argument in values_dict:
        arg_type = arguments[argument]['type']
        value = values_dict[argument]
        if is_digit(value) and arg_type in ('int', 'integer'):
            values_dict[argument] = int(value)
        elif is_float(value) and arg_type in ('float', 'decimal'):
            values_dict[argument] = float(value)
        elif value.lower() in ('true', 'false') and arg_type in ('bool', 'boolean'):
            values_dict[argument] = value.lower() == 'true'
        else:
            values_dict[argument] = cast_to_type(arg_type, value)

